package com.ds.goroute.controller;
import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.CreateActivityOrderRequest;import com.ds.goroute.dto.response.ActivityOrderResponse;import com.ds.goroute.service.ActivityCommerceService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/v1/api/activity-orders") @RequiredArgsConstructor
public class ActivityOrderController {private final ActivityCommerceService s;@PostMapping public ResponseEntity<BaseResponse<ActivityOrderResponse>> create(Authentication a,@Valid @RequestBody CreateActivityOrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.createOrder(user(a),r)));}@GetMapping public ResponseEntity<BaseResponse<List<ActivityOrderResponse>>> list(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listMyOrders(user(a),page,size)));}@GetMapping("/{id}")public ResponseEntity<BaseResponse<ActivityOrderResponse>> get(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.getMyOrder(user(a),id)));}@PostMapping("/{id}/cancel")public ResponseEntity<BaseResponse<ActivityOrderResponse>> cancel(Authentication a,@PathVariable UUID id,@RequestParam(required=false)String reason,@RequestParam(required=false)Long expectedVersion){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.cancelMyOrder(user(a),id,reason,expectedVersion)));}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
